const bodies: Partial<Record<LocaleCode, Partial<PolicyBodySet>>> = { en, 'zh-hans': zhHans, 'zh-hant': zhHant, ja, ko, de, fr, es, ru, ar };

export function getPolicyBody(policy: PolicyKey, locale = 'en'): PolicyBodyCopy {
  return bodies[locale as LocaleCode]?.[policy] ?? en[policy];
}

export function renderPolicyHtml(
  html: string,
  locale: string,
  values: { legalName?: string; email?: string } = {},
): string {
  const email = values.email ?? 'contact@panorama-sg.com';
  const replacements: Record<string, string> = {
    LEGAL_NAME: values.legalName ?? 'Panorama Scholarly Group Ltd',
    EMAIL_LINK: `<a href="mailto:${email}">${email}</a>`,
    CONTACT_HREF: localizePath('/about/contact/', locale),
    PRIVACY_HREF: localizePath('/privacy/', locale),
    ETHICS_HREF: localizePath('/standards/ethics/', locale),
    OA_HREF: localizePath('/standards/open-access/', locale),
    ACCESSIBILITY_HREF: localizePath('/accessibility/', locale),
  };
  return Object.entries(replacements).reduce((result, [key, value]) => result.replaceAll(`{{${key}}}`, value), html);
}
